package android.app; public class NotificationManager {public static final int IMPORTANCE_LOW=2;public static final NotificationManager INSTANCE=new NotificationManager();public static boolean failNotify;public static int notifications,cancels;public static Notification last;public void createNotificationChannel(NotificationChannel c){}public void notify(int id,Notification n){if(failNotify)throw new SecurityException("sensitive notification error");notifications++;last=n;}public void cancel(int id){cancels++;}public static void reset(){failNotify=false;notifications=0;cancels=0;last=null;} }